"use client";

import { useEffect, useState } from "react";
import { useReducedMotion } from "framer-motion";
import { useFinanceData } from "@/components/finance/useFinanceData";
import { AllocationDonut, RollingReturnsLine, DrawdownArea, ConcentrationBar, TreemapGrid } from "@/components/finance/charts";

const InvestmentCharts = () => {
  const { data, isLoading, isError } = useFinanceData("investments");
  const isReducedMotion = useReducedMotion();

  if (isLoading) return <div>Loading...</div>;
  if (isError) return <div>Error...</div>;

  if (!data) return <div>Empty</div>;

  const { allocation, rollingReturns, drawdown, concentration, treemap } = data;

  return (
    <div className="flex flex-col gap-4">
      <AllocationDonut data={allocation} />
      <RollingReturnsLine data={rollingReturns} />
      <DrawdownArea data={drawdown} />
      <ConcentrationBar data={concentration} />
      <TreemapGrid data={treemap} />
    </div>
  );
};

export default InvestmentCharts;
